          "body": "同一個角的六個三角函數互相牽連。最重要的是平方關係 sin²θ + cos²θ = 1（單位圓上的點到原點距離為 1）與商數關係 tan θ = sin θ / cos θ。已知其中一個函數值就能求出其他值，但要依象限決定正負。\n\n倒數關係：csc θ = 1/sin θ、sec θ = 1/cos θ、cot θ = 1/tan θ。餘角關係：sin(90° − θ) = cos θ、tan(90° − θ) = cot θ，也就是「餘角的函數互換」。\n\n統測常見的化簡題：已知 sin θ 與象限求 tan θ，或把含 sec、csc 的式子先化成 sin、cos 再代值。",
