          "body": "直線的傾斜程度用斜率 m = (y₂ − y₁)/(x₂ − x₁) 表示，它也等於斜角 θ（直線與 x 軸正向的夾角，0° ≤ θ < 180°）的正切：m = tan θ。鉛直線的斜角為 90°，斜率不存在。\n\n常用的直線方程式：點斜式 y − y₀ = m(x − x₀)；斜截式 y = mx + b；截距式 x/a + y/b = 1（a、b 分別為 x、y 截距，皆不為 0）；一般式 ax + by + c = 0，其斜率為 −a/b。已知兩點時，先求斜率再用點斜式最快。\n\n配置圖上的管線、道路中心線都是直線；截距的正負則對應線與坐標軸的交點在哪一側（114 年統測以截距與斜率的關係命題）。",
