          "body": "三角測量用來求無法直接量到的高度或距離。仰角是視線在水平線上方時與水平線的夾角，俯角是視線在水平線下方時與水平線的夾角，兩者都從水平線量起。\n\n常用方法：①在同一直線上的兩點分別量仰角，列兩個 tan 關係式消去未知的水平距離；②量出兩觀測點的距離與兩個角，用正弦定理解三角形；③量兩邊與夾角，用餘弦定理求第三邊。\n\n例：從地面 A 點測大樓頂仰角 30°，朝大樓前進 100 m 到 B 點測得仰角 60°。在 △ABD 中外角 60° = 30° + ∠ADB，得 ∠ADB = 30°，所以 △ABD 是等腰三角形，BD = AB = 100 m，大樓高 h = BD sin 60° = 50√3 m。111 年統測則在三個觀測點（30°、45°、60°）之間求兩段距離的比。",
          "formula": "仰角、俯角：視線與水平線的夾角\n兩點仰角法：h = d/(cot α − cot β)（兩觀測點相距 d，遠處仰角 α、近處仰角 β，α < β）\n正弦定理求不可到達的距離：AC/sin B = AB/sin C",
