            "畫圖：大樓高 h，B 點到樓底距離 x，A 點到樓底距離 x + 100。 ｜為什麼：把空間情境轉成兩個直角三角形。",
            "列式：tan 60° = h/x ⇒ x = h/√3；tan 30° = h/(x + 100) ⇒ x + 100 = √3h。 ｜為什麼：兩個觀測點各提供一個方程式。",
            "相減：√3h − h/√3 = 100 ⇒ (2/√3)h = 100 ⇒ h = 50√3 ≈ 86.6 m。 ｜為什麼：消去未知的水平距離 x。",
            "驗算：x = 50 m，tan 60° = 50√3/50 = √3。 ｜為什麼：代回確認兩個仰角條件都成立。"
