          "body": "指數律：aᵐ·aⁿ = aᵐ⁺ⁿ、aᵐ/aⁿ = aᵐ⁻ⁿ、(aᵐ)ⁿ = aᵐⁿ、(ab)ⁿ = aⁿbⁿ（a、b > 0）。規定 a⁰ = 1、a⁻ⁿ = 1/aⁿ，並把分數指數定義為根式：a^(1/n) = ⁿ√a、a^(p/q) = (q√a)ᵖ。\n\n工程經驗公式常出現分數指數，例如鋼構造建築物基本振動週期的經驗式 T = 0.085h^(3/4)（113 年統測）。若 A 棟的週期是 B 棟的 2 倍，則 (h_A/h_B)^(3/4) = 2 ⇒ h_A/h_B = 2^(4/3) ≈ 2.52。\n\n比較大小時先化成同底或同指數：2^(1/2) 與 3^(1/3) 同時 6 次方，得 2³ = 8 與 3² = 9，所以 3^(1/3) 較大。",
