          "body": "遞增遞減：在區間內 f′(x) > 0 ⇒ f 遞增；f′(x) < 0 ⇒ f 遞減。\n\n極值：f′(a) = 0 且 f′ 在 a 左右由正變負 ⇒ 相對極大；由負變正 ⇒ 相對極小。也可用二階導數：f′(a) = 0 且 f″(a) < 0 為極大、f″(a) > 0 為極小。閉區間上的最大、最小值要比較「臨界點」與「端點」的函數值。\n\n112 年：f(x) = x³ + 3x² − 72x − 74，f′(x) = 3(x + 6)(x − 4) ⇒ 相對極大在 x = −6、相對極小在 x = 4。114 年：f(x) = 2x³ − 3x² − 12x + 1，f′(x) = 6(x − 2)(x + 1) ⇒ 在 (−∞, −1) 與 (2, ∞) 遞增。\n\n最佳化問題（紙盒、圍籬、成本）：設變數 → 寫出目標函數與定義域 → 微分找臨界點 → 檢查是極大或極小，並確認在定義域內。",
